            requestAnimationFrame(update);
        } else {
            elevatorCar.leftDoor.position.x = targetX;
            elevatorCar.rightDoor.position.x = targetX;
            doorAnimating = false;
            done();
        }
    }

    requestAnimationFrame(update);
}
