function animateDoors(open, done) {
    const doorWidth = SHAFT_WIDTH / 2 - 1;
    const currentOpen = !doorAnimating ? (elevatorCar.leftDoor.position.x === -SHAFT_WIDTH / 4 + 0.5) : true;

